process microsite.return.project:
  let returnDocument = one($msDocument, "path")
  call microsite.return.decorate

process microsite.return.decorate:
  when not(includes($result, "id=\"microsite-return\"")):
    let returnMarkup = $result
    port text.split { value = $returnDocument; pattern = "/" } → returnParts
    port text.join { values = map(range(add(count($returnParts), -1)), "level", "../"); separator = "" } → returnPrefix
    let input = {
      tag = "link";
      attrs = {
        rel = "stylesheet";
        href = concat($returnPrefix, "assets/microsite-return.css?v=return-2")
      };
      children = list()
    }
    call html.serialize
    let returnHead = concat($result, "\n")
    let input = {
      tag = "a";
      attrs = {
        id = "microsite-return";
        class = "microsite-return";
        href = concat($returnPrefix, "index.html#microsites");
        "aria-label" = "Back to Aaron Alderman’s main website";
        "data-site" = at($returnParts, 0)
      };
      children = list(
        { tag = "span"; attrs = { "aria-hidden" = "true" }; children = list("←") },
        { tag = "span"; attrs = {  }; children = list("Back to Aaron Alderman") }
      )
    }
    call html.serialize
    let returnBody = concat("\n", $result, "\n")
    port text.replaceAll {
      value = $returnMarkup;
      search = "</head>";
      replacement = concat($returnHead, "</head>")
    } → returnMarkup
    port text.replaceAll {
      value = $returnMarkup;
      search = "</body>";
      replacement = concat($returnBody, "</body>")
    } → result

process microsite.return.all:
  each subjects("isa", "StandalonePage") as returnPage:
    let returnCanonical = one($returnPage, "canonical")
    port text.matches { value = $returnCanonical; pattern = "/$" } → returnDirectory
    when and(
      $returnDirectory,
      includes($returnCanonical, one("site", "origin")),
      not(eq($returnCanonical, one("site", "origin")))
    ):
      port text.replaceAll { value = $returnCanonical; search = one("site", "origin"); replacement = "" } → returnRoute
      let returnDocument = concat($returnRoute, "index.html")
      port file.read { path = $returnDocument } → result
      call microsite.return.decorate
      port file.write { path = $returnDocument; text = $result } → _
